 sliders=[
  ('gamma', T('위험 회피 정도 γ (나)', 'Risk aversion γ (you)'), 0, 8, 0.25, 1.5, T('0이면 평균만 보고, 클수록 가장 나쁜 자리를 걱정해요', '0 looks only at the average; larger worries more about the worst position')),
  ('popMean', T('집단의 평균 γ', 'Average γ of the group'), 0, 8, 0.25, 2, T('③번 그래프에서 1,000명의 평균 위험 회피 정도', 'Average risk aversion of the 1,000 people in graph ③')),
  ('popSd', T('집단의 γ 퍼짐', 'Spread of γ in the group'), 0, 3, 0.25, 1, T('사람마다 위험을 싫어하는 정도가 얼마나 다른지', 'How much people differ in how much they dislike risk')),
 ],
 selects=[('rule', T('선택 규칙', 'Choice rule'), [('eu', T('기대효용 (γ 사용)', 'Expected utility (uses γ)')), ('avg', T('평균 극대화', 'Maximize the average')), ('maximin', T('최소 극대화', 'Maximize the minimum'))], 'eu',
          T('나는 어떤 기준으로 고를지', 'What rule you use to choose'))],
